var Dissolve = require('dissolve');
var URLSafeBase64 = require('urlsafe-base64');

module.exports = deserialize;
function deserialize(treeHash) {
    var result = {
        error: null,
    };

    var branches = [];
    var parser = new Dissolve()
        .string('name', 6)
        .tap(function () {
            if (this.vars.name !== 'mendel') {
                result.error = error('not generated by mendel');
            }
        })
        .uint8('version')
        .tap(function () {
            if (this.vars.version !== 2) {
                result.error = error(': version mismatch');
            }
        })
        .loop('branches', function (end) {
            this.uint8('index').tap(function () {
                if (this.vars.index === 255) {
                    return end();
                } else if (this.vars.index === 254) {
                    return this.uint16('next').tap(function () {
                        branches.push(this.vars.next);
                    });
                }
                branches.push(this.vars.index);
            });
        })
        .tap(function () {
            this.vars.branches = branches;
        })
        .uint16('files')
        .buffer('hash', 20)
        .tap(function () {
            result.decoded = this.vars;
        });

    try {
        var binary = URLSafeBase64.decode(treeHash);
        parser.write(binary);
    } catch (e) {
        result.error = error('bad base64 input');
    }

    var ok = result.decoded && Buffer.isBuffer(result.decoded.hash);
    if (!ok) {
        result.error = result.error || error('short or missing sha');
    }

    return result;
}

function error(msg) {
    var error = new Error('Invalid hash: ' + msg);
    error.code = 'BADHASH';
    return error;
}

const path = require('path');
const { test } = require('tap');
const rimraf = require('rimraf');
const fs = require('fs');
const Pipeline = require('../../mendel-pipeline');
const appPath = path.join(__dirname, './css-samples');
const buildPath = path.join(appPath, 'build');

rimraf.sync(buildPath);
rimraf.sync(path.join(appPath, '.mendelipc'));

test('mendel-outlet-css sanity test', function (t) {
    t.plan(4);

    process.chdir(appPath);
    process.env.MENDELRC = '.mendelrc';

    const mendel = new Pipeline();
    mendel.run(function (error) {
        try {
            if (error) {
                console.error(error);
                return t.bailout('should create manifest but failed');
            }

            const css = fs.readFileSync(
                path.join(buildPath, 'main.css'),
                'utf8'
            );

            t.notMatch(css, /background: red/);
            t.match(css, /padding: 0/);
            t.match(css, /background: blue/);
            // From LESS
            t.match(css, /background: #1111ff/);
        } finally {
            // Daemon leaves IPC handles open; same as CLI after build.
            if (typeof mendel.onForceExit === 'function') {
                try {
                    mendel.onForceExit();
                } catch (e) {
                    /* ignore */
                }
            }
            setImmediate(() => process.exit(t.passing() ? 0 : 1));
        }
    });
});

const path = require('path');
const fs = require('fs');
const rimraf = require('rimraf');

const monorepoPackages = path.resolve(__dirname, '../../..');
const outletManifest = path.join(monorepoPackages, 'mendel-outlet-manifest');
const parserPlaintext = path.join(monorepoPackages, 'mendel-parser-plaintext');
const mendelPipeline = path.resolve(__dirname, '../..');

exports.parserPlaintext = parserPlaintext;

/**
 * Stage a read-only fixture into a disposable, gitignored run directory.
 *
 * The fixture is the single source of truth and is never written to; the run
 * directory holds everything a build generates (.mendelrc, .mendelipc, build/)
 * as real files next to links back to the fixture's sources.
 *
 * Each top-level child of the fixture is linked individually rather than the
 * fixture root, because node and mendel find node_modules by walking up from
 * the requiring file to the project root: linking only ./app would make that
 * walk land in the run directory, which has no node_modules of its own.
 *
 * A fixture's dependencies live in `stubs/` and are staged as `node_modules/`,
 * because a directory actually named node_modules cannot be committed.
 *
 * Pass `copy: true` for tests that mutate their sources (watch-mode recovery,
 * error handling) so the mutation lands in the run directory instead of the
 * repository.
 */
exports.stageFixture = function stageFixture(
    fixtureDir,
    runName,
    { copy = false, runRoot } = {}
) {
    if (!fs.existsSync(fixtureDir)) {
        throw new Error(`stageFixture: no fixture at ${fixtureDir}`);
    }

    const runDir = path.join(
        runRoot || path.resolve(__dirname, '..'),
        '.mendel-runs',
        runName
    );
    rimraf.sync(runDir);
    fs.mkdirSync(runDir, { recursive: true });

    const place = (target, linkPath) => {
        if (copy) return fs.cpSync(target, linkPath, { recursive: true });
        try {
            fs.symlinkSync(
                path.relative(path.dirname(linkPath), target),
                linkPath
            );
        } catch (e) {
            // Windows refuses symlinks without privileges; a copy is
            // equivalent for a read-only fixture.
            if (e.code !== 'EPERM' && e.code !== 'EACCES') throw e;
            fs.cpSync(target, linkPath, { recursive: true });
        }
    };

    fs.readdirSync(fixtureDir)
        .filter((entry) => entry !== 'README.md' && entry !== 'expect')
        .forEach((entry) => {
            const target = path.join(fixtureDir, entry);
            if (entry === 'stubs') {
                const nodeModules = path.join(runDir, 'node_modules');
                fs.mkdirSync(nodeModules, { recursive: true });
                fs.readdirSync(target).forEach((pkg) =>
                    place(path.join(target, pkg), path.join(nodeModules, pkg))
                );
                return;
            }
            place(target, path.join(runDir, entry));
        });

    fs.mkdirSync(path.join(runDir, 'build'), { recursive: true });
    return runDir;
};

exports.buildPathFor = function buildPathFor(appPath) {
    return path.join(appPath, 'build');
};

exports.baseYaml = function baseYaml({
    types = '',
    transforms = '',
    entry,
    extraTop = '',
    bundleExtra = '',
}) {
    return `base-config:
  id: base
  dir: ./app
  outdir: ./build

variation-config:
  variation-dirs: []
  variations: {}
${extraTop}
transforms:${transforms ? '\n' + transforms : ' {}'}

types:
  js:
    extensions:
      - .js
${types}

outlets:
  - id: manifest
    plugin: ${outletManifest}
    options:
      uglify: false
      envify: false

bundles:
  main:
    outlet: manifest
    manifest: main.manifest.json
${bundleExtra ? bundleExtra + '\n' : ''}    entries:
      - ./${entry}
`;
};

exports.runBuild = function runBuild(appPath, yaml, callback) {
    fs.writeFileSync(path.join(appPath, '.mendelrc'), yaml);

    const prevCwd = process.cwd();
    process.chdir(appPath);
    delete process.env.MENDELRC;
    delete process.env.NODE_ENV;
    delete process.env.MENDEL_ENV;

    delete require.cache[require.resolve(mendelPipeline)];
    const MendelV2 = require(mendelPipeline);
    const mendel = new MendelV2();

    mendel.run((error) => {
        process.chdir(prevCwd);
        if (typeof mendel.onForceExit === 'function') {
            try {
                mendel.onForceExit();
            } catch (e) {
                /* ignore */
            }
        }
        callback(error);
    });
};

const Mocha = require('mocha');
const MendelClient = require('mendel-pipeline/client');
const { execWithRegistry, exec } = require('mendel-exec');
const fs = require('fs');
const { globSync } = require('glob');
const errorMapper = require('mendel-exec/source-mapper');

const DEFAULT_OPTIONS = {
    watch: false,
    bail: false,
};

const client = new MendelClient({
    environment: 'test',
    noout: true,
}).run();

function MendelRunner(filePaths, options = {}) {
    const watch = options.watch || false;
    // Watch is a feature of mendel, not mocha.
    options = Object.assign({}, DEFAULT_OPTIONS, options, { watch: false });

    if (options.prelude) {
        options.prelude = globSync(options.prelude);
    }

    client.on('ready', function () {
        // Populate the global sandbox
        const sandbox = {};
        // Expose to mocha options for others.
        options.context = sandbox;

        // Istanbul support: it writes to global so make instrumentation
        // running in different context share object with the global one.
        sandbox.__coverage__ = global.__coverage__ = {};

        const mocha = new Mocha(options);

        const entries = client.registry.getEntriesByGlob(filePaths);
        entries.forEach((entry) => {
            // Pre-require populates mocha globals like before, beforeEach, and
            // etc...
            mocha.suite.emit('pre-require', sandbox, entry.id, mocha);

            options.prelude.forEach((file) => {
                const entry = client.registry.getEntry('./' + file);
                const id = entry ? entry.id : file;
                const source = entry
                    ? entry.source
                    : fs.readFileSync(file, 'utf8');

                exec(id, source, {
                    sandbox,
                    resolver(from, dep) {
                        const fromEntry = client.registry.getEntry(from);
                        if (!fromEntry) return null;
                        const depNorm = fromEntry.deps[dep]
                            ? fromEntry.deps[dep].main
                            : null;
                        if (!depNorm || depNorm.indexOf('/') < 0) return null;
                        const entries =
                            client.registry.getExecutableEntries(depNorm);
                        if (!entries) return null;
                        return entries.values().next().value;
                    },
                });
            });

            const variationConf = client.config.variationConfig.variations.find(
                ({ chain }) => chain[0] === entry.variation
            );
            const module = execWithRegistry(
                client.registry,
                entry.normalizedId,
                [variationConf],
                sandbox
            );
            mocha.suite.emit('require', module, entry.id, mocha);
        });

        const runner = mocha.run();
        runner.on('fail', (test, error) => {
            error.stack = errorMapper(error.stack, client.registry);
        });

        if (!watch) {
            runner.on('end', () => process.exit(runner.failures));
        }
    });

    client.on('change', function () {
        console.log('Mendel detected file change. Waiting for bundle...');
    });
}

module.exports = MendelRunner;

